const {chromium}=require('playwright');
(async()=>{const b=await chromium.launch({headless:true,executablePath:'/ms-playwright/chromium-1187/chrome-linux/chrome',args:['--no-sandbox']});const p=await b.newPage();p.on('pageerror',e=>console.log('PAGEERROR',e.message));p.on('console',m=>{if(m.type()==='error')console.log('CONSOLE',m.text())});const base='http://host.docker.internal:18089';await p.goto(base,{waitUntil:'domcontentloaded'});await p.waitForTimeout(700);console.log('initial',await p.locator('#loginDialog').isVisible().catch(()=>false),await p.title());if(!await p.locator('#loginDialog').isVisible().catch(()=>false)) await p.locator('#userButton').click();await p.waitForFunction(()=>!!document.querySelector('#loginDialog')?.open,{timeout:10000});await p.locator('#loginEmail').fill('nwx-ui-test@example.invalid');await p.locator('#loginPassword').fill('TestOnlyAdminPassword_2026!');await p.locator('#loginForm button[type=submit]').click();await p.waitForTimeout(1000);console.log('dialog',await p.locator('#loginDialog').evaluate(e=>({open:e.open,html:e.innerHTML.slice(0,500)})));const catalog=await p.evaluate(async()=>{let r=await fetch('/api/geography/catalog');return [r.status,await r.json()]});console.log('catalog',JSON.stringify(catalog).slice(0,700));console.log('viewitems',await p.locator('[data-view]').evaluateAll(es=>es.map(e=>[e.getAttribute('data-view'),e.className,e.getAttribute('aria-current')])));await p.locator('[data-view="opportunities"]').first().evaluate(e=>e.click());await p.waitForTimeout(1200);console.log('filters',await p.locator('#tableNationalGeoFilters').evaluate(e=>({hidden:e.hidden,display:getComputedStyle(e).display,text:e.innerText.slice(0,300)})).catch(e=>String(e)));console.log('geo',await p.locator('#tableGeographicFilter').count(),await p.locator('#tableGeographicFilter').isVisible().catch(()=>false));await b.close()})().catch(e=>{console.error(e);process.exit(1)});